1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Canonicalises a raw address string: trim and collapse internal whitespace runs to a
7	 * single space, upper-case, and expand common street-type abbreviations
8	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is the
9	 * form stored and returned as {@code address}, and the form every address comparison
10	 * (household duplicate detection and the shared household id) is done against.
11	 * Normalization is idempotent, so re-normalizing an already-normalized address is a
12	 * no-op. Returns the empty string when no address text remains, so callers reject a
13	 * blank-after-normalization address with a 400.
14	 */
15	final class AddressNormalizer {
16	
17	    private AddressNormalizer() {
18	    }
19	
20	    static String normalize(String raw) {
21	        if (raw == null) {
22	            return "";
23	        }
24	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
